/* llm-plugin: 스레드 정보 카드 아래 명령 안내 (plugins/t3-guide/build_theme.py로 생성) */
[data-thread-details-card]::after {
  content: ""; display: block; flex-basis: 100%; width: 100%; aspect-ratio: 290 / 520;
  margin-top: 4px; background: no-repeat center top / 100% auto;
}
.dark [data-thread-details-card]::after { background-image: url("data:image/svg+xml;base64,"); }
:root:not(.dark) [data-thread-details-card]::after { background-image: url("data:image/svg+xml;base64,"); }
